      "title": "Un fine settimana a Napoli",
      "text": "La settimana scorsa Riccardo ha trascorso un pomeriggio a Napoli per un fine settimana. Aveva deciso di visitare senza fretta, ma all'inizio non conosceva tutti i dettagli. Per questo ha chiesto informazioni a la sua amica Elena, che le ha spiegato con calma come organizzarsi.\n\nDurante l'attività, Riccardo ha osservato le persone e ha scoperto una soluzione pratica. Non tutto è andato come previsto, tuttavia ha cambiato piano senza perdere la calma. la sua amica Elena ha apprezzato il suo modo di ascoltare prima di scegliere.\n\nAlla fine hanno condiviso ciò che avevano imparato e hanno preparato un breve messaggio per chi arriverà dopo. Riccardo pensa che l'esperienza sia stata utile perché le ha dato parole nuove e più fiducia per agire da sola.",
