      "text": "Elena è a la cucina di casa. Incontra sua nonna e saluta con un sorriso. Elena vuole raccontare la famiglia, perciò ascolta con attenzione e usa parole semplici. sua nonna risponde lentamente e indica ciò che può aiutare.\n\nPoi i due parlano di una piccola situazione della giornata. Elena fa una domanda, riceve una risposta e ringrazia. Prima di andare via, decidono di ripetere le parole più utili: così la prossima conversazione sarà più facile.",
