    "vocabulary": [],
    "dialogue": [],
    "reading": {
      "title": "Ricette di famiglia",
      "text": "La settimana scorsa Elena ha trascorso un pomeriggio a la cucina di casa. Aveva deciso di raccontare la famiglia, ma all'inizio non conosceva tutti i dettagli. Per questo ha chiesto informazioni a sua nonna, che le ha spiegato con calma come organizzarsi.\n\nDurante l'attività, Elena ha osservato le persone e ha scoperto una soluzione pratica. Non tutto è andato come previsto, tuttavia ha cambiato piano senza perdere la calma. sua nonna ha apprezzato il suo modo di ascoltare prima di scegliere.\n\nAlla fine hanno condiviso ciò che avevano imparato e hanno preparato un breve messaggio per chi arriverà dopo. Elena pensa che l'esperienza sia stata utile perché le ha dato parole nuove e più fiducia per agire da sola.",
      "questions": [
        "Di che cosa parla il testo?",
        "Che cosa fa prima la protagonista?",
        "Quale ruolo ha la seconda persona?",
        "Perché il gruppo collabora?",
        "Qual è l’obiettivo comune?"
      ],
      "parts": [
        "La settimana scorsa Elena ha trascorso un pomeriggio a la cucina di casa. Aveva deciso di raccontare la famiglia, ma all'inizio non conosceva tutti i dettagli. Per questo ha chiesto informazioni a sua nonna, che le ha spiegato con calma come organizzarsi.",
        "Durante l'attività, Elena ha osservato le persone e ha scoperto una soluzione pratica. Non tutto è andato come previsto, tuttavia ha cambiato piano senza perdere la calma. sua nonna ha apprezzato il suo modo di ascoltare prima di scegliere.",
        "Alla fine hanno condiviso ciò che avevano imparato e hanno preparato un breve messaggio per chi arriverà dopo. Elena pensa che l'esperienza sia stata utile perché le ha dato parole nuove e più fiducia per agire da sola."
      ]
    },
