      "text": "Marta è a la pista ciclabile. Incontra il suo vicino Davide e saluta con un sorriso. Marta vuole muoversi in sicurezza, perciò ascolta con attenzione e usa parole semplici. il suo vicino Davide risponde lentamente e indica ciò che può aiutare.\n\nPoi i due parlano di una piccola situazione della giornata. Marta fa una domanda, riceve una risposta e ringrazia. Prima di andare via, decidono di ripetere le parole più utili: così la prossima conversazione sarà più facile.",
