      "text": "La settimana scorsa Elisa ha trascorso un pomeriggio a un muro del quartiere. Aveva deciso di partecipare a un progetto artistico, ma all'inizio non conosceva tutti i dettagli. Per questo ha chiesto informazioni a un artista locale, che le ha spiegato con calma come organizzarsi.\n\nDurante l'attività, Elisa ha osservato le persone e ha scoperto una soluzione pratica. Non tutto è andato come previsto, tuttavia ha cambiato piano senza perdere la calma. un artista locale ha apprezzato il suo modo di ascoltare prima di scegliere.\n\nAlla fine hanno condiviso ciò che avevano imparato e hanno preparato un breve messaggio per chi arriverà dopo. Elisa pensa che l'esperienza sia stata utile perché le ha dato parole nuove e più fiducia per agire da sola.",
